import json
import primitive_api as p

log = []

def acc():
    return p.list_accessible_objects()

def find(objlist, name):
    for o in objlist:
        if o.get("name") == name:
            return o
    return None

def step(label, r):
    msg = getattr(r, "message", None)
    if msg is None:
        msg = str(r)
    log.append(f"{label}: {str(msg)[:220]}")

def direction_to(name):
    near = p.list_nearby_objects(query=name)
    o = find(near, name)
    if not o:
        return None, None
    return o.get("direction"), o.get("distance")

def move_toward(name):
    d, dist = direction_to(name)
    if not d:
        return False
    if "south" in d:
        r = p.move_direction("south")
    elif "north" in d:
        r = p.move_direction("north")
    elif "east" in d:
        r = p.move_direction("east")
    elif "west" in d:
        r = p.move_direction("west")
    else:
        return False
    step(f"move toward {name} (dir={d}, dist={dist})", r)
    return True

def go_and_pick(name, max_steps=10):
    for _ in range(max_steps):
        a = acc()
        o = find(a, name)
        if o:
            r = p.pickup_object(o["uuid"])
            step(f"pickup {name} ({o['uuid']})", r)
            return True
        if not move_toward(name):
            log.append(f"lost track of {name}")
            return False
    return False

# 1) shovel
got_shovel = go_and_pick("shovel")
# 2) radiocarbon meter (on table)
got_meter = go_and_pick("radiocarbon meter")
# 3) flag
got_flag = go_and_pick("flag")

log.append("inventory: " + json.dumps([(o.get("name"), o.get("uuid")) for o in p.list_inventory()], default=str))
log.append("accessible: " + json.dumps([(o.get("name"), o.get("uuid")) for o in acc()], default=str))
log.append("verify: " + json.dumps(p.check_success(), default=str)[:600])

print("SHOVEL", got_shovel, "METER", got_meter, "FLAG", got_flag)
for line in log:
    print(line)

import json
import primitive_api as p

def last():
    return p.observe_world().get("lastActionMessage", "")

def soils_near():
    near = p.list_nearby_objects()
    objs = near.get("objects", near) if isinstance(near, dict) else near
    out = []
    for k, v in objs.items():
        if k == "same_location":
            continue
        for o in v:
            if o.get("name") == "soil":
                out.append(o)
    out.sort(key=lambda o: o.get("distance", 99))
    return out

def axis(d):
    for c in ("south", "north", "east", "west"):
        if c in d:
            return c
    return None

def approach(sel_name):
    for _ in range(8):
        near = p.list_nearby_objects()
        objs = near.get("objects", near) if isinstance(near, dict) else near
        t = None
        for k, v in objs.items():
            if k == "same_location":
                continue
            for o in v:
                if o.get("name") == sel_name:
                    t = o
                    break
            if t:
                break
        if not t:
            return None
        d = axis(t["direction"])
        if not d:
            return None
        if t["distance"] <= 1:
            p.rotate_direction(d)
            return t
        p.rotate_direction(d)
        p.move_direction(d)
    return None

def dig_and_date(site):
    p.teleport_to_location(site)
    age = None
    for _ in range(4):
        ss = soils_near()
        if not ss:
            break
        t = ss[0]
        d = axis(t["direction"])
        if t["distance"] <= 1:
            p.rotate_direction(d)
            p.use_object(4766, t["uuid"])
            break
        p.rotate_direction(d)
        p.move_direction(d)
    acc = p.list_accessible_objects()
    arts = [o for o in acc if o.get("name") == "ancient artifact"]
    for a in arts:
        p.use_object(60834, a["uuid"])
        m = last()
        for tok in m.split():
            if tok.isdigit() and int(tok) > 1000:
                age = int(tok)
                break
    return age

ages = {}
ages["dig site 2"] = dig_and_date("dig site 2")
ages["dig site 3"] = dig_and_date("dig site 3")
